"use client";

import * as React from "react";
import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from "recharts";

import { cn } from "@/registry/luma/lib/utils";
import { AdminShell } from "@/registry/luma/blocks/admin-shell";
import {
  AdminOverview,
  AdminOverviewHeader,
  AdminOverviewItem,
  AdminOverviewItemActions,
  AdminOverviewItemMeta,
  AdminOverviewItemReason,
  AdminOverviewItemTitle,
  AdminOverviewList,
  AdminOverviewMeta,
  AdminOverviewTitle,
  type AdminOverviewSeverity,
} from "@/registry/luma/ui/admin-overview";
import { Button } from "@/registry/luma/ui/button";
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/registry/luma/ui/chart";

type MetricCardData = {
  id: string;
  label: string;
  value: string;
  hint: string;
};

type QueueItem = {
  id: string;
  severity: AdminOverviewSeverity;
  title: string;
  reason: string;
  action: string;
};

const METRICS: MetricCardData[] = [
  {
    id: "active-learners",
    label: "활성 학습자",
    value: "12,480",
    hint: "전주 대비 +4.2%",
  },
  {
    id: "sessions-today",
    label: "오늘 학습 세션",
    value: "3,216",
    hint: "전일 대비 −1.1%",
  },
  {
    id: "publish-pending",
    label: "게시 대기 코스",
    value: "5",
    hint: "검토 필요 2건 포함",
  },
  {
    id: "interventions",
    label: "개입 필요",
    value: "18",
    hint: "7일 미접속 포함",
  },
];

const QUEUE_ITEMS: QueueItem[] = [
  {
    id: "publish-reading",
    severity: "urgent",
    title: "「중급 읽기」 코스 게시 승인 대기",
    reason: "내일 공개 일정이 잡혀 있습니다.",
    action: "검토",
  },
  {
    id: "interventions",
    severity: "urgent",
    title: "학습자 개입 필요 7건",
    reason: "7일 이상 미접속·반복 오답이 겹칩니다.",
    action: "열기",
  },
  {
    id: "dropout-honorifics",
    severity: "warning",
    title: "레슨 「존댓말 연습」 이탈률 상승",
    reason: "최근 7일 완료율이 38% 하락했습니다.",
    action: "분석",
  },
  {
    id: "item-review",
    severity: "warning",
    title: "문항 검수 대기 12건",
    reason: "새 어휘 유닛 초안이 검증을 통과하지 못했습니다.",
    action: "검수",
  },
  {
    id: "writing-preview",
    severity: "info",
    title: "「쓰기 기초」 draft → preview 이동 가능",
    reason: "검토 코멘트가 모두 해소되었습니다.",
    action: "게시 흐름",
  },
  {
    id: "audit-permissions",
    severity: "info",
    title: "감사 로그: 권한 변경 3건",
    reason: "오늘 오전 운영자 계정 설정이 변경되었습니다.",
    action: "보기",
  },
];

const chartConfig = {
  completions: {
    label: "레슨 완료",
    color: "var(--primary)",
  },
} satisfies ChartConfig;

const LESSON_COMPLETIONS = [
  { day: "7/6", completions: 842 },
  { day: "7/7", completions: 918 },
  { day: "7/8", completions: 876 },
  { day: "7/9", completions: 1004 },
  { day: "7/10", completions: 1128 },
  { day: "7/11", completions: 968 },
  { day: "7/12", completions: 734 },
  { day: "7/13", completions: 892 },
  { day: "7/14", completions: 954 },
  { day: "7/15", completions: 1012 },
  { day: "7/16", completions: 1086 },
  { day: "7/17", completions: 1194 },
  { day: "7/18", completions: 1048 },
  { day: "7/19", completions: 812 },
  { day: "7/20", completions: 936 },
  { day: "7/21", completions: 988 },
  { day: "7/22", completions: 1056 },
  { day: "7/23", completions: 1132 },
  { day: "7/24", completions: 1218 },
  { day: "7/25", completions: 1094 },
  { day: "7/26", completions: 846 },
  { day: "7/27", completions: 972 },
  { day: "7/28", completions: 1038 },
  { day: "7/29", completions: 1116 },
  { day: "7/30", completions: 1182 },
  { day: "7/31", completions: 1264 },
  { day: "8/1", completions: 1148 },
  { day: "8/2", completions: 902 },
  { day: "8/3", completions: 1068 },
  { day: "8/4", completions: 1196 },
] as const;

function MetricCard({ metric }: { metric: MetricCardData }) {
  return (
    <div
      data-slot="home-admin-metric"
      className="flex min-w-0 flex-col gap-1 rounded-3xl bg-muted/60 px-4 py-3.5"
    >
      <p className="text-[11px] font-medium text-muted-foreground">{metric.label}</p>
      <p className="font-heading text-xl font-semibold tracking-[-0.03em] tabular-nums sm:text-2xl">
        {metric.value}
      </p>
      <p className="text-[11px] leading-4 text-muted-foreground">{metric.hint}</p>
    </div>
  );
}

function LessonCompletionsChart() {
  return (
    <section
      data-slot="home-admin-chart"
      className="flex flex-col gap-4 rounded-[1.75rem] bg-muted/55 p-4 sm:p-5"
      aria-labelledby="home-admin-chart-title"
    >
      <header className="flex items-baseline justify-between gap-3 px-0.5">
        <div>
          <h2 id="home-admin-chart-title" className="text-sm font-medium tracking-[-0.01em]">
            일별 레슨 완료
          </h2>
          <p className="mt-0.5 text-xs text-muted-foreground">최근 30일</p>
        </div>
        <p className="text-xs tabular-nums text-muted-foreground">총 30,624</p>
      </header>

      <ChartContainer
        config={chartConfig}
        className="aspect-auto h-56 w-full sm:h-64"
        initialDimension={{ width: 640, height: 224 }}
      >
        <AreaChart data={[...LESSON_COMPLETIONS]} margin={{ left: 0, right: 8, top: 8, bottom: 0 }}>
          <defs>
            <linearGradient id="home-admin-completions" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--color-completions)" stopOpacity={0.28} />
              <stop offset="100%" stopColor="var(--color-completions)" stopOpacity={0.02} />
            </linearGradient>
          </defs>
          <CartesianGrid vertical={false} strokeDasharray="3 3" />
          <XAxis dataKey="day" tickLine={false} axisLine={false} minTickGap={28} tickMargin={8} />
          <YAxis
            tickLine={false}
            axisLine={false}
            width={40}
            tickMargin={4}
            domain={["dataMin - 80", "dataMax + 40"]}
          />
          <ChartTooltip
            content={
              <ChartTooltipContent labelFormatter={(value) => `${value}`} indicator="line" />
            }
          />
          <Area
            type="monotone"
            dataKey="completions"
            stroke="var(--color-completions)"
            fill="url(#home-admin-completions)"
            strokeWidth={2}
            dot={false}
            activeDot={{ r: 4 }}
          />
        </AreaChart>
      </ChartContainer>
    </section>
  );
}

function ActionQueue() {
  return (
    <AdminOverview data-slot="home-admin-queue">
      <AdminOverviewHeader>
        <AdminOverviewTitle>오늘 처리할 항목</AdminOverviewTitle>
        <AdminOverviewMeta>{QUEUE_ITEMS.length}건</AdminOverviewMeta>
      </AdminOverviewHeader>
      <AdminOverviewList>
        {QUEUE_ITEMS.map((item) => (
          <AdminOverviewItem key={item.id} severity={item.severity}>
            <AdminOverviewItemTitle>{item.title}</AdminOverviewItemTitle>
            <AdminOverviewItemReason>{item.reason}</AdminOverviewItemReason>
            <AdminOverviewItemMeta severity={item.severity} />
            <AdminOverviewItemActions>
              <Button size="sm" variant="outline" type="button">
                {item.action}
              </Button>
            </AdminOverviewItemActions>
          </AdminOverviewItem>
        ))}
      </AdminOverviewList>
    </AdminOverview>
  );
}

/**
 * Unified operator home for a Korean learning service: metrics, lesson-completion chart, and action queue.
 */
export function HomeAdmin({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <AdminShell
      data-slot="home-admin"
      activeNav="home"
      title="홈"
      description="운영 현황을 한눈에 봅니다"
      showSearch
      className={cn(className)}
      {...props}
    >
      <section
        data-slot="home-admin-metrics"
        className="grid grid-cols-[repeat(auto-fit,minmax(min(100%,10rem),1fr))] gap-3"
        aria-label="주요 지표"
      >
        {METRICS.map((metric) => (
          <MetricCard key={metric.id} metric={metric} />
        ))}
      </section>

      <LessonCompletionsChart />
      <ActionQueue />
    </AdminShell>
  );
}

export default HomeAdmin;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Analytics01Icon,
  Audit01Icon,
  BookOpen01Icon,
  Home01Icon,
  Logout03Icon,
  Menu01Icon,
  Notification03Icon,
  Robot01Icon,
  Search01Icon,
  Settings02Icon,
  UserIcon,
  UserMultipleIcon,
} from "@hugeicons/core-free-icons";

import { cn } from "@/registry/luma/lib/utils";
import { Avatar, AvatarFallback } from "@/registry/luma/ui/avatar";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/registry/luma/ui/breadcrumb";
import { Button } from "@/registry/luma/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/registry/luma/ui/dropdown-menu";
import { Input } from "@/registry/luma/ui/input";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/registry/luma/ui/sheet";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
} from "@/registry/luma/ui/sidebar";

export type AdminBreadcrumbItem = {
  label: string;
  href?: string;
};

export type AdminNavId =
  | "home"
  | "courses"
  | "users"
  | "analytics"
  | "settings"
  | "agents"
  | "audit";

type NavItem = {
  id: AdminNavId;
  label: string;
  icon: typeof Home01Icon;
};

type NavGroup = {
  id: string;
  label: string;
  items: NavItem[];
};

const NAV_GROUPS: NavGroup[] = [
  {
    id: "overview",
    label: "개요",
    items: [{ id: "home", label: "홈", icon: Home01Icon }],
  },
  {
    id: "content",
    label: "콘텐츠",
    items: [{ id: "courses", label: "코스", icon: BookOpen01Icon }],
  },
  {
    id: "learners",
    label: "학습자",
    items: [{ id: "users", label: "사용자", icon: UserMultipleIcon }],
  },
  {
    id: "insights",
    label: "인사이트",
    items: [{ id: "analytics", label: "분석", icon: Analytics01Icon }],
  },
  {
    id: "system",
    label: "시스템",
    items: [
      { id: "settings", label: "설정", icon: Settings02Icon },
      { id: "agents", label: "에이전트", icon: Robot01Icon },
      { id: "audit", label: "감사 로그", icon: Audit01Icon },
    ],
  },
];

function preventNav(event: React.MouseEvent | React.SyntheticEvent) {
  event.preventDefault();
}

function AdminNavGroups({
  activeNav,
  onNavigate,
}: {
  activeNav: AdminNavId;
  onNavigate?: () => void;
}) {
  return (
    <>
      {NAV_GROUPS.map((group) => (
        <SidebarGroup key={group.id}>
          <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {group.items.map((item) => {
                const current = item.id === activeNav;
                return (
                  <SidebarMenuItem key={item.id}>
                    <SidebarMenuButton
                      isActive={current}
                      tooltip={item.label}
                      render={
                        <a
                          href={`#${item.id}`}
                          aria-label={item.label}
                          aria-current={current ? "page" : undefined}
                          onClick={(event) => {
                            preventNav(event);
                            onNavigate?.();
                          }}
                        />
                      }
                    >
                      <HugeiconsIcon icon={item.icon} strokeWidth={2} />
                      <span>{item.label}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      ))}
    </>
  );
}

function AdminBrand() {
  return (
    <div className="flex items-center gap-2.5 px-0.5">
      <span className="grid size-7 shrink-0 place-items-center rounded-xl bg-foreground text-[0.65rem] font-semibold text-background">
        L
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-semibold tracking-[-0.01em]">Luma</p>
        <p className="truncate text-[11px] text-muted-foreground">운영</p>
      </div>
    </div>
  );
}

function AdminSidebar({ activeNav }: { activeNav: AdminNavId }) {
  return (
    <Sidebar
      collapsible="none"
      className="hidden h-full min-h-0 w-(--sidebar-width) shrink-0 border-e border-sidebar-border/80 @[56rem]/admin-shell:flex"
    >
      <SidebarHeader>
        <AdminBrand />
      </SidebarHeader>
      <SidebarContent>
        <AdminNavGroups activeNav={activeNav} />
      </SidebarContent>
    </Sidebar>
  );
}

function AdminHeader({
  title,
  description,
  breadcrumb,
  showSearch = false,
  onOpenNav,
}: {
  title: string;
  description?: string;
  breadcrumb?: AdminBreadcrumbItem[];
  showSearch?: boolean;
  onOpenNav: () => void;
}) {
  const hasBreadcrumb = Boolean(breadcrumb?.length);

  return (
    <header
      data-slot="admin-shell-header"
      className="sticky top-0 z-20 flex h-14 shrink-0 items-center gap-2 border-b border-border/50 bg-background/90 px-3 backdrop-blur-xl @[40rem]/admin-shell:h-15 @[40rem]/admin-shell:gap-3 @[40rem]/admin-shell:px-5 @[56rem]/admin-shell:gap-4 @[56rem]/admin-shell:px-6"
    >
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        className="shrink-0 rounded-full @[56rem]/admin-shell:hidden"
        aria-label="메뉴 열기"
        onClick={onOpenNav}
      >
        <HugeiconsIcon icon={Menu01Icon} strokeWidth={2} />
      </Button>

      <div className="min-w-0 flex-1">
        {hasBreadcrumb ? (
          <>
            <h1 className="sr-only">{title}</h1>
            <Breadcrumb className="min-w-0">
              <BreadcrumbList className="flex-wrap gap-1 @[40rem]/admin-shell:gap-1.5">
                {breadcrumb!.map((item) => (
                  <React.Fragment key={`${item.label}-${item.href ?? "page"}`}>
                    <BreadcrumbItem className="shrink-0">
                      <BreadcrumbLink
                        href={item.href ?? "#"}
                        onClick={preventNav}
                        className="text-sm"
                      >
                        {item.label}
                      </BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator className="shrink-0" />
                  </React.Fragment>
                ))}
                <BreadcrumbItem className="min-w-0">
                  <BreadcrumbPage className="block truncate font-heading text-sm font-semibold tracking-[-0.02em] @[40rem]/admin-shell:text-base">
                    {title}
                  </BreadcrumbPage>
                </BreadcrumbItem>
              </BreadcrumbList>
            </Breadcrumb>
          </>
        ) : (
          <h1 className="truncate font-heading text-sm font-semibold tracking-[-0.02em] @[40rem]/admin-shell:text-base">
            {title}
          </h1>
        )}
        {description ? (
          <p className="mt-0.5 hidden truncate text-xs text-muted-foreground @[40rem]/admin-shell:block">
            {description}
          </p>
        ) : null}
      </div>

      {showSearch ? (
        <div className="relative ms-auto hidden min-w-0 max-w-[14rem] flex-1 @[48rem]/admin-shell:block @[64rem]/admin-shell:max-w-sm">
          <HugeiconsIcon
            icon={Search01Icon}
            strokeWidth={2}
            className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground"
          />
          <Input
            type="search"
            placeholder="코스·학습자·문항 검색"
            className="h-9 ps-9"
            aria-label="코스·학습자·문항 검색"
          />
        </div>
      ) : (
        <div className="ms-auto" />
      )}

      <div className="flex shrink-0 items-center gap-1">
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          className="relative rounded-full"
          aria-label="알림 3건"
        >
          <HugeiconsIcon icon={Notification03Icon} strokeWidth={2} />
          <span className="absolute top-1 right-1 grid min-w-4 place-items-center rounded-full bg-foreground px-1 text-[0.6rem] leading-4 font-semibold text-background tabular-nums">
            3
          </span>
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={<Button variant="ghost" size="icon-sm" className="rounded-full" />}
            aria-label="프로필 메뉴 열기"
          >
            <Avatar size="sm">
              <AvatarFallback>수</AvatarFallback>
            </Avatar>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-52">
            <DropdownMenuGroup>
              <DropdownMenuLabel>수진</DropdownMenuLabel>
              <DropdownMenuItem>
                <HugeiconsIcon icon={UserIcon} strokeWidth={2} />
                프로필
              </DropdownMenuItem>
              <DropdownMenuItem>
                <HugeiconsIcon icon={Settings02Icon} strokeWidth={2} />
                설정
              </DropdownMenuItem>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant="destructive">
              <HugeiconsIcon icon={Logout03Icon} strokeWidth={2} />
              로그아웃
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

export function AdminShell({
  activeNav,
  title,
  description,
  breadcrumb,
  showSearch = false,
  className,
  contentClassName,
  children,
  ...props
}: {
  activeNav: AdminNavId;
  title: string;
  description?: string;
  breadcrumb?: AdminBreadcrumbItem[];
  showSearch?: boolean;
  contentClassName?: string;
  children: React.ReactNode;
} & React.ComponentProps<"div">) {
  const [navOpen, setNavOpen] = React.useState(false);

  return (
    <div
      data-slot="admin-shell"
      className={cn(
        "@container/admin-shell relative flex h-full min-h-svh w-full overflow-hidden bg-background",
        className,
      )}
      {...props}
    >
      <SidebarProvider className="relative flex h-full min-h-0 w-full flex-1 overflow-hidden">
        <AdminSidebar activeNav={activeNav} />

        <Sheet open={navOpen} onOpenChange={setNavOpen}>
          <SheetContent
            side="left"
            className="w-[min(100%,18rem)] bg-sidebar p-0 text-sidebar-foreground [&>button]:hidden"
          >
            <SheetHeader className="sr-only">
              <SheetTitle>운영 메뉴</SheetTitle>
              <SheetDescription>운영 화면 탐색 메뉴</SheetDescription>
            </SheetHeader>
            <div className="flex h-full w-full flex-col">
              <div className="flex h-14 items-center border-b border-sidebar-border/80 px-3">
                <AdminBrand />
              </div>
              <div className="min-h-0 flex-1 overflow-auto p-2">
                <Sidebar collapsible="none" className="h-auto w-full bg-transparent">
                  <SidebarContent>
                    <AdminNavGroups activeNav={activeNav} onNavigate={() => setNavOpen(false)} />
                  </SidebarContent>
                </Sidebar>
              </div>
            </div>
          </SheetContent>
        </Sheet>

        <SidebarInset className="min-h-0 min-w-0 flex-1 overflow-hidden">
          <AdminHeader
            title={title}
            description={description}
            breadcrumb={breadcrumb}
            showSearch={showSearch}
            onOpenNav={() => setNavOpen(true)}
          />
          <div
            data-slot="admin-shell-main"
            className={cn(
              "@container/admin-main flex min-h-0 flex-1 flex-col gap-6 overflow-auto px-3 py-5 @[40rem]/admin-shell:gap-8 @[40rem]/admin-shell:px-5 @[40rem]/admin-shell:py-7 @[56rem]/admin-shell:px-6 @[56rem]/admin-shell:py-8",
              contentClassName,
            )}
          >
            {children}
          </div>
        </SidebarInset>
      </SidebarProvider>
    </div>
  );
}
